import{_ as i,o as a,c as t,aj as n}from"./chunks/framework.C6uXqnaX.js";const g=JSON.parse('{"title":"LLM prompts and AI IDE setup","description":"","frontmatter":{},"headers":[],"relativePath":"en/ai/develop-with-ai.md","filePath":"en/ai/develop-with-ai.md"}'),e={name:"en/ai/develop-with-ai.md"};function l(h,s,p,r,k,o){return a(),t("div",null,s[0]||(s[0]=[n('<h1 id="llm-prompts-and-ai-ide-setup" tabindex="-1">LLM prompts and AI IDE setup <a class="header-anchor" href="#llm-prompts-and-ai-ide-setup" aria-label="Permalink to &quot;LLM prompts and AI IDE setup&quot;">​</a></h1><p>Generating code with large language models (LLMs) is a rapidly growing area of interest for developers. While LLMs are often capable of generating working code it can be a challenge to generate code for consistently evolving frameworks like Angular.</p><p>Advanced instructions and prompting are an emerging standard for supporting modern code generation with domain specific details. This section contains curated content and resources to support more accurate code generation for Angular and LLMs.</p><h2 id="custom-prompts-and-system-instructions" tabindex="-1">Custom Prompts and System Instructions <a class="header-anchor" href="#custom-prompts-and-system-instructions" aria-label="Permalink to &quot;Custom Prompts and System Instructions&quot;">​</a></h2><p>Improve your experience generating code with LLMs by using one of the following custom, domain specific files.</p><div class="info custom-block"><p class="custom-block-title">NOTE</p><p>These files will be updated on a regular basis staying up to date with Angular&#39;s conventions.</p></div><p>Here is a set of instructions to help LLMs generate correct code that follows Angular best practices. This file can be included as system instructions to your AI tooling or included along with your prompt as context.</p><div class="language-md vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">md</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">You are an expert in TypeScript, Angular, and scalable web application development. You write functional, maintainable, performant, and accessible code following Angular and TypeScript best practices.</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">## TypeScript Best Practices</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Use strict type checking</span></span>\n<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Prefer type inference when the type is obvious</span></span>\n<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Avoid the </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">`any`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> type; use </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">`unknown`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> when type is uncertain</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">## Angular Best Practices</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Always use standalone components over NgModules</span></span>\n<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Must NOT set </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">`standalone: true`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> inside Angular decorators. It&#39;s the default in Angular v20+.</span></span>\n<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Do NOT set </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">`changeDetection: ChangeDetectionStrategy.OnPush`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> explicitly. </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">`OnPush`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> is the default in Angular v22+.</span></span>\n<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Use signals for state management</span></span>\n<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Implement lazy loading for feature routes</span></span>\n<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Do NOT use the </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">`@HostBinding`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> and </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">`@HostListener`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> decorators. Put host bindings inside the </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">`host`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> object of the </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">`@Component`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> or </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">`@Directive`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> decorator instead</span></span>\n<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Use </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">`NgOptimizedImage`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> for all static images.</span></span>\n<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">  -</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> `NgOptimizedImage`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> does not work for inline base64 images.</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">## Accessibility Requirements</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> It MUST pass all AXE checks.</span></span>\n<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> It MUST follow all WCAG AA minimums, including focus management, color contrast, and ARIA attributes.</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">## Components</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Keep components small and focused on a single responsibility</span></span>\n<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Use </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">`input()`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> and </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">`output()`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> functions instead of decorators</span></span>\n<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Use </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">`model()`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> for two-way bound properties with </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">`[(prop)]`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> syntax instead of pairing </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">`input()`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> with </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">`output()`</span></span>\n<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Use </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">`computed()`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> for derived state</span></span>\n<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Use </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">`linkedSignal()`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> for state derived from multiple reactive sources that must stay synchronized</span></span>\n<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Prefer inline templates for small components</span></span>\n<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Prefer Signal Forms (</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">`@angular/forms/signals`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) for new forms. They are stable in Angular v22+ and provide signal-based state, type-safe field access, and schema-based validation</span></span>\n<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> When not using Signal Forms, prefer Reactive forms instead of Template-driven ones</span></span>\n<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Do NOT use </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">`ngClass`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, use </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">`class`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> bindings instead</span></span>\n<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Do NOT use </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">`ngStyle`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, use </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">`style`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> bindings instead</span></span>\n<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Do NOT import </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">`CommonModule`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, import only the directives and pipes the template uses, such as </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">`AsyncPipe`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> or </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">`DatePipe`</span></span>\n<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> When using external templates/styles, use paths relative to the component TS file.</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">## State Management</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Use signals for local component state</span></span>\n<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Use </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">`computed()`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> for derived state</span></span>\n<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Keep state transformations pure and predictable</span></span>\n<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Do NOT use </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">`mutate`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> on signals, use </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">`update`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> or </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">`set`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> instead</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">## Templates</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Keep templates simple and avoid complex logic</span></span>\n<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Use native control flow (</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">`@if`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">`@for`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">`@switch`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) instead of </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">`*ngIf`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">`*ngFor`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">`*ngSwitch`</span></span>\n<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Use the async pipe to handle observables</span></span>\n<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Do not assume globals like (</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">`new Date()`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) are available.</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">## Services</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Design services around a single responsibility</span></span>\n<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Prefer the </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">`@Service`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> decorator over </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">`@Injectable({providedIn: &#39;root&#39;})`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> for new singleton services (Angular v22+)</span></span>\n<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Use the </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">`inject()`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> function instead of constructor injection</span></span></code></pre></div><p><a download href="https://angular.dev/assets/context/best-practices.md" target="_blank">Click here to download the best-practices.md file.</a></p><h2 id="rules-files" tabindex="-1">Rules Files <a class="header-anchor" href="#rules-files" aria-label="Permalink to &quot;Rules Files&quot;">​</a></h2><p>Several tools, such as <a href="https://antigravity.google?utm_source=adev&amp;utm_medium=website&amp;utm_campaign=BUILD_WITH_AI_ANGULAR&amp;utm_term=angular_devrel&amp;utm_content=build_with_ai_angular_antigravity" target="_blank">Antigravity</a> have rules files useful for providing critical context to LLMs.</p><table tabindex="0"><thead><tr><th style="text-align:left;">Environment/IDE</th><th style="text-align:left;">Rules File</th><th style="text-align:left;">Installation Instructions</th></tr></thead><tbody><tr><td style="text-align:left;">Antigravity</td><td style="text-align:left;"><a download href="https://angular.dev/assets/context/GEMINI.md" target="_blank">GEMINI.md</a></td><td style="text-align:left;"><a href="https://antigravity.google/docs/rules-workflows" target="_blank">Configure <code>GEMINI.md</code></a></td></tr><tr><td style="text-align:left;">Copilot powered IDEs</td><td style="text-align:left;"><a download="copilot-instructions.md" href="https://angular.dev/assets/context/guidelines.md" target="_blank">copilot-instructions.md</a></td><td style="text-align:left;"><a href="https://code.visualstudio.com/docs/copilot/copilot-customization#_custom-instructions" target="_blank">Configure <code>.github/copilot-instructions.md</code></a></td></tr><tr><td style="text-align:left;">Cursor</td><td style="text-align:left;"><a download href="https://angular.dev/assets/context/angular-20.mdc" target="_blank">cursor.md</a></td><td style="text-align:left;"><a href="https://docs.cursor.com/context/rules" target="_blank">Configure <code>cursorrules.md</code></a></td></tr><tr><td style="text-align:left;">JetBrains IDEs</td><td style="text-align:left;"><a download href="https://angular.dev/assets/context/AGENTS.md" target="_blank">AGENTS.md</a></td><td style="text-align:left;"><a href="https://junie.jetbrains.com/docs/guidelines-and-memory.html#how-junie-cli-discovers-guidelines" target="_blank">Configure <code>AGENTS.md</code></a></td></tr><tr><td style="text-align:left;">VS Code</td><td style="text-align:left;"><a download=".instructions.md" href="https://angular.dev/assets/context/guidelines.md" target="_blank">.instructions.md</a></td><td style="text-align:left;"><a href="https://code.visualstudio.com/docs/copilot/copilot-customization#_custom-instructions" target="_blank">Configure <code>.instructions.md</code></a></td></tr><tr><td style="text-align:left;">Windsurf</td><td style="text-align:left;"><a download href="https://angular.dev/assets/context/guidelines.md" target="_blank">guidelines.md</a></td><td style="text-align:left;"><a href="https://docs.windsurf.com/windsurf/cascade/memories#rules" target="_blank">Configure <code>guidelines.md</code></a></td></tr></tbody></table><h2 id="angular-cli-mcp-server-setup" tabindex="-1">Angular CLI MCP Server setup <a class="header-anchor" href="#angular-cli-mcp-server-setup" aria-label="Permalink to &quot;Angular CLI MCP Server setup&quot;">​</a></h2><p>The Angular CLI includes an experimental <a href="https://modelcontextprotocol.io/" target="_blank" rel="noreferrer">Model Context Protocol (MCP) server</a> that allows AI assistants in your development environment to interact with the Angular CLI.</p><p><a href="/en/ai/mcp"><strong>Learn how to set up the Angular CLI MCP Server</strong></a></p><h2 id="providing-context-with-llms-txt" tabindex="-1">Providing Context with <code>llms.txt</code> <a class="header-anchor" href="#providing-context-with-llms-txt" aria-label="Permalink to &quot;Providing Context with `llms.txt`&quot;">​</a></h2><p><code>llms.txt</code> is a proposed standard for websites designed to help LLMs better understand and process their content. The Angular team has developed two versions of this file to help LLMs and tools that use LLMs for code generation to create better modern Angular code.</p><ul><li><a href="https://angular.dev/llms.txt" target="_blank">llms.txt</a> - an index file providing links to key files and resources.</li><li><a href="https://angular.dev/assets/context/llms-full.txt" target="_blank">llms-full.txt</a> - a more robust compiled set of resources describing how Angular works and how to build Angular applications.</li></ul><p>Be sure to check out the <a href="/en/ai">overview page</a> for more information on how to integrate AI into your Angular applications.</p>',19)]))}const E=i(e,[["render",l]]);export{g as __pageData,E as default};
